function setBpm(v){const resumePreparation=preparing&&transport==='paused';if(preparing&&clamp(Math.round(+v)||100,60,200)!==bpm)cancelPreparation();performanceBeat+=(ac.currentTime-performanceAt)*bpm/60;performanceAt=ac.currentTime;const old=bpm,beat=playlistPosition();bpm=clamp(Math.round(+v)||100,60,200);if(playlistMode&&transport==='playing'){plBeat=beat;plAnchorBeat=beat;plAnchorTime=ac.currentTime;plDisplayBeat=beat;plDisplayTime=ac.currentTime;}if(transport==='playing'&&!playlistMode)nextTime=rebaseClock(queue,lastPlayed,nextTime,ac.currentTime,old,bpm);$('#bpm').value=bpm;$('#bpmNumber').value=bpm;changed();if(resumePreparation&&!preparing)startPrepared();}$('#bpm').oninput=e=>setBpm(e.target.value);$('#bpmNumber').oninput=e=>{const value=+e.target.value;if(value>=60&&value<=200)setBpm(value);};$('#bpmNumber').onchange=e=>setBpm(e.target.value);let taps=[];$('#tapTempo').onclick=()=>{let t=performance.now();if(t-(taps.at(-1)||0)>2000)taps=[];taps.push(t);if(taps.length>6)taps.shift();if(taps.length>1)setBpm(60000/((taps.at(-1)-taps[0])/(taps.length-1)));fx('tap');};$('#metronome').onchange=e=>metro=e.target.checked;$('#loopSong').onchange=e=>{if(['playlist','mixer'].includes(activeView)){plEditingBeat=playlistPosition();playlist.loop=e.target.checked;playlistEditor.render();}else{loop=e.target.checked;if(previewPlaylist)previewPlaylist.loop=loop;}changed();};$('#beatMaster').oninput=e=>{mix.gain.setTargetAtTime(+e.target.value/100,ac.currentTime,.01);changed();};
