function editor(){soundOptions();let p=b(),buf=buffers.get(p.sampleId);$('#samplePad').textContent='PAD '+String(selected+1).padStart(2,'0');$('#sampleName').value=p.name;for(let[id,value]of[['sampleStart',p.start],['sampleEnd',p.end]]){let el=$('#'+id);el.max=buf.duration;el.value=value;}$('#startValue').textContent=p.start.toFixed(3)+' s';$('#endValue').textContent=p.end.toFixed(3)+' s';$('#sampleDuration').textContent=buf.duration.toFixed(3)+' s · '+buf.sampleRate+' Hz · '+buf.numberOfChannels+' CH';$('#sampleRange').textContent='SELECTED '+(p.end-p.start).toFixed(3)+' s';$('#padPitch').value=p.pitch;$('#pitchValue').textContent=(p.pitch>0?'+':'')+p.pitch+' st';$('#padVolume').value=p.volume*100;$('#volumeValue').textContent=Math.round(p.volume*100)+'%';$('#padLoop').checked=p.loop;$('#padMute').checked=p.mute;$('#padSolo').checked=p.solo;wave();}
function wave(){let c=$('#sampleWave'),cx=c.getContext('2d'),p=b(),buf=buffers.get(p.sampleId),a=buf.getChannelData(0),w=c.width,h=c.height;cx.clearRect(0,0,w,h);cx.fillStyle='#10162c';cx.fillRect(0,0,w,h);let sx=p.start/buf.duration*w,ex=p.end/buf.duration*w;cx.fillStyle='#63d3cb22';cx.fillRect(sx,0,ex-sx,h);cx.strokeStyle=PAD_COLORS[selected];cx.lineWidth=1.4;cx.beginPath();for(let x=0;x<w;x++){let lo=Math.floor(x*a.length/w),hi=Math.max(lo+1,Math.floor((x+1)*a.length/w)),min=1,max=-1;for(let i=lo;i<hi;i++){min=Math.min(min,a[i]);max=Math.max(max,a[i]);}cx.moveTo(x,h/2+min*h*.42);cx.lineTo(x,h/2+max*h*.42);}cx.stroke();for(let x of[sx,ex]){cx.fillStyle='#77edda';cx.fillRect(x-2,0,4,h);cx.fillRect(x-6,0,12,15);}cx.fillStyle='#77edda';cx.font='11px Outfit';cx.fillText('IN',sx+8,16);cx.fillText('OUT',Math.max(0,ex-30),h-8);}
$('#sampleName').oninput=e=>{b().name=e.target.value.trim().slice(0,32)||'My sample';padUI();sequenceUI();changed();};for(let[id,key]of[['padPitch','pitch'],['padVolume','volume'],['sampleStart','start'],['sampleEnd','end']])$('#'+id).oninput=e=>{let value=+e.target.value,p=b(),buf=buffers.get(p.sampleId);if(key==='volume')value/=100;if(key==='start')value=clamp(value,0,p.end-.005);if(key==='end')value=clamp(value,p.start+.005,buf.duration);p[key]=value;if(key==='volume')for(const [source,m] of voiceMeta)if(m.index===selected)m.gain.gain.setTargetAtTime(value,ac.currentTime,.01);editor();changed();};for(let[id,key]of[['padLoop','loop'],['padMute','mute'],['padSolo','solo']])$('#'+id).onchange=e=>{b()[key]=e.target.checked;if(key==='mute'||key==='solo')for(const [source,m] of voiceMeta)if(!padAllowed(pads[m.index])){if(m.event){if(m.start>ac.currentTime)events=events.filter(e=>e!==m.event);else m.event.duration=Math.min(m.event.duration,Math.max(.001,ac.currentTime-m.start));}try{source.stop();}catch{}}padUI();changed();};
let handle=null;$('#sampleWave').onpointerdown=e=>{e.preventDefault();let r=e.target.getBoundingClientRect(),t=(e.clientX-r.left)/r.width*buffers.get(b().sampleId).duration;handle=Math.abs(t-b().start)<Math.abs(t-b().end)?'start':'end';e.target.setPointerCapture(e.pointerId);setHandle(e);};function setHandle(e){if(!handle)return;let r=$('#sampleWave').getBoundingClientRect(),p=b(),buf=buffers.get(p.sampleId),t=clamp((e.clientX-r.left)/r.width*buf.duration,0,buf.duration);p[handle]=handle==='start'?Math.min(t,p.end-.005):Math.max(t,p.start+.005);editor();changed();}$('#sampleWave').onpointermove=setHandle;$('#sampleWave').onpointerup=()=>handle=null;$('#sampleWave').onpointercancel=()=>handle=null;
let previewSource=null;$('#samplePreview').onclick=()=>{if(previewSource){try{previewSource.stop();}catch{}previewSource=null;$('#samplePreview').textContent='▶ PREVIEW';return;}let p=b(),buf=buffers.get(p.sampleId);previewSource=ac.createBufferSource();previewSource.buffer=buf;previewSource.playbackRate.value=2**(p.pitch/12);let gain=ac.createGain();gain.gain.value=p.volume;previewSource.connect(gain);gain.connect(mix);let s=previewSource;sources.add(s);s.onended=()=>{s.disconnect();gain.disconnect();sources.delete(s);if(previewSource===s)previewSource=null;if(!disposed)$('#samplePreview').textContent='▶ PREVIEW';};s.start(0,p.start,p.end-p.start);$('#samplePreview').textContent='■ STOP PREVIEW';};
$('#sampleTrim').onclick=()=>{let p=b(),buf=buffers.get(p.sampleId),start=Math.floor(p.start*buf.sampleRate),end=Math.ceil(p.end*buf.sampleRate),newId=uid();buffers.set(newId,bufferFrom(Array.from({length:buf.numberOfChannels},(_,i)=>buf.getChannelData(i).slice(start,end)),buf.sampleRate));p.sampleId=newId;p.start=0;p.end=buffers.get(newId).duration;editor();changed();notify('Trim applied. This pad now uses only your selected audio.');};$('#sampleReset').onclick=()=>{let id='builtin-0-'+selected;if(!buffers.has(id))buffers.set(id,bufferFrom([synthPCM(selected)]));pads[selected]={name:PAD_NAMES[selected],sampleId:id,pitch:0,volume:.8,start:0,end:buffers.get(id).duration,loop:false,mute:false,solo:false};editor();padUI();sequenceUI();changed();};
