function nameModal(title,value,callback){return nameKeyboard(modal,{title,value,description:'Saved locally with '+player().name+'’s profile.',onSave:callback});}

function serializedBuffers(){let data={},used=new Set([...pads.map(p=>p.sampleId),...patterns.flatMap(p=>p.kind==='audio'?[p.sampleId]:(p.playlistPads||[]).map(s=>s.sampleId)),...events.map(e=>e.p.sampleId)]);for(let[id,buf]of buffers)if(used.has(id))data[id]={sampleRate:buf.sampleRate,channels:Array.from({length:buf.numberOfChannels},(_,i)=>buf.getChannelData(i).slice()),...(originalFiles.has(id)?{original:originalFiles.get(id)}:{})};return data;}
