async function bankOptions(){let banks=await mediaAll('bank');$('#bankSelect').innerHTML=[0,1,2].map((i)=>`<option value="builtin-${i}">${['Neon','Punch','Cosmic'][i]} kit · built-in</option>`).join('')+banks.map(b=>`<option value="${b.id}">${esc(b.name)} · ${esc(player(b.owner)?.name||'saved')}</option>`).join('');if([...$('#bankSelect').options].some(o=>o.value===bankSelection))$('#bankSelect').value=bankSelection;}
$('#bankSelect').onchange=async e=>{if(!await ask('Switch sound banks?','This replaces the current pad sounds and mixer settings. Save your custom bank first if you want to keep it.')){e.target.value=bankSelection;return;}stopSources();try{if(e.target.value.startsWith('builtin-')){let i=+e.target.value.slice(-1);makeKit(i);bankName=['Neon','Punch','Cosmic'][i]+' kit';}else{let data=await mediaGet(e.target.value);for(let[id,s]of Object.entries(data.samples))buffers.set(id,bufferFrom(s.channels,s.sampleRate));pads=structuredClone(data.pads);bankName=data.name;}bankSelection=e.target.value;padUI();editor();sequenceUI();changed();}catch(error){e.target.value=bankSelection;notify(error.message,'error');}};
$('#bankSave').onclick=()=>nameModal('Name your sound bank',bankName,async name=>{try{let used=new Set(pads.map(p=>p.sampleId)),all=serializedBuffers(),id=uid();await mediaPut({id,type:'bank',owner:DB.active,name,pads:structuredClone(pads),samples:Object.fromEntries(Object.entries(all).filter(([id])=>used.has(id))),updatedAt:Date.now()});bankName=name;bankSelection=id;await bankOptions();notify('Your custom sound bank is saved.');}catch(e){notify('Could not save bank: '+e.message,'error');}});
async function saveProject(draft=false){if(!draft)clearTimeout(draftTimer);let id=draft?'beat-draft-'+owner:(projectId||uid());await mediaPut({id,type:draft?'draft':'music',owner:owner,name:projectName,data:projectData(),updatedAt:Date.now()});if(!draft){projectId=id;dirty=false;let count=patterns.reduce((n,p)=>n+(p.kind==='audio'?1:p.kind==='notes'?p.notes.length:p.matrix.flat().filter(Boolean).length),0)+events.length;if(count>=4)creativeMilestone('beat');notify('Music project saved. Pick it up any time.');fx('win');}}
