function showBattleResults(){battle=false;modal(`<div class="eyebrow">BEAT BATTLE · TWO ORIGINAL TAKES</div><h2>Two players. Two sounds.</h2><p>Listen together and decide your favorite. Musical taste doesn’t affect competitive leaderboards.</p><div class="beat-battle-results">${battleEntries.map((e,i)=>`<article><span class="avatar" style="--player:${player(e.owner).color}">${player(e.owner).avatar}</span><h3>${esc(player(e.owner).name)}</h3><p>${e.events.length} hits · ${e.duration.toFixed(1)} s</p><button class="btn secondary" data-listen="${i}">▶ LISTEN</button><button class="btn primary" data-battle-save="${i}">SAVE PROJECT</button></article>`).join('')}</div>`,d=>{d.querySelectorAll('[data-listen]').forEach(b=>b.onclick=async()=>{try{stopSources();let e=battleEntries[+b.dataset.listen],buffer=await renderEvents(e.events,e.duration),s=ac.createBufferSource();s.buffer=buffer;s.connect(mix);sources.add(s);s.onended=()=>{s.disconnect();sources.delete(s);};s.start();}catch(e){notify(e.message,'error');}});d.querySelectorAll('[data-battle-save]').forEach(b=>b.onclick=async()=>{let e=battleEntries[+b.dataset.battleSave];try{await mediaPut({id:uid(),type:'music',owner:e.owner,name:player(e.owner).name+' Beat Battle',data:e.data,updatedAt:Date.now()});if(e.events.length>=4)creativeMilestone('beat',e.owner);notify('Beat Battle take saved for '+player(e.owner).name);}catch(e){notify(e.message,'error');}});});}
$('#beatExit').onclick=async()=>{pianoEditor.cancel();playlistEditor.cancel();if(mic?.busy||mic?.unsaved){if(!await ask('Leave your microphone sample?','Unsaved microphone audio will be discarded. Save it to a track first to keep it.'))return;}if(exporting){notify('Wait for your MP3 to finish exporting first.');return;}if(recording)stopRecording();if(dirty){try{await saveProject(true);}catch(e){if(!await ask('Leave without saving?','Autosave failed. Your unsaved music edits will be lost.'))return;}}exit();};$('#beatFull').onclick=()=>document.querySelector('#fullscreen').click();
function render(){mixerEditor.update();if(disposed)return;let now=ac.currentTime;while(queue.length&&queue[0].at<=now){let next=queue.shift();lastPlayed=next.absolute;$('#beatPosition').textContent=String(Math.floor(next.step/16)+1).padStart(2,'0')+' : '+String(next.step%16+1).padStart(2,'0');host.querySelectorAll('.step.playing').forEach(x=>x.classList.remove('playing'));if(next.pattern!==patternId&&songMode){patternId=next.pattern;sequenceUI();}if(next.pattern===patternId){const playing=host.querySelectorAll(`[data-step="${next.step}"]`);playing.forEach(x=>x.classList.add('playing'));if(activeView==='sequence'&&playing[0]){const scroll=$('.sequence-scroll'),a=playing[0].getBoundingClientRect(),r=scroll.getBoundingClientRect();if(a.right>r.right||a.left<r.left+162)scroll.scrollLeft=Math.max(0,scroll.scrollLeft+a.left-r.left-190);}}}visuals=visuals.filter(v=>v.until>now);host.querySelectorAll('[data-pad]').forEach(p=>{p.classList.toggle('lit',[...held.values()].some(h=>h?.index===+p.dataset.pad)||visuals.some(v=>v.index===+p.dataset.pad&&v.at<=now));});host.querySelectorAll('[data-seq-pad],[data-track]').forEach(p=>p.classList.toggle('sounding',visuals.some(v=>v.index===+(p.dataset.seqPad??p.dataset.track)&&v.at<=now)));let c=$('#audioViz'),cx=c.getContext('2d'),a=spectrum();cx.clearRect(0,0,c.width,c.height);for(let i=0;i<30;i++){let value=a[i*3]/255;cx.fillStyle=i%3===0?'#b48bff':'#53dfcd';cx.fillRect(i*7,c.height*(1-value),4,Math.max(2,c.height*value));}if(activeView==='piano'){const beat=playlistPosition();pianoEditor.position(beat);if(playlistMode)$('#beatPosition').textContent=String(Math.floor(beat/4)+1).padStart(2,'0')+' : '+String(Math.floor(beat%4)+1).padStart(2,'0');}if(activeView==='playlist'){const beat=playlistPosition();playlistEditor.update(beat);if(playlistMode)$('#beatPosition').textContent=String(Math.floor(beat/4)+1).padStart(2,'0')+' : '+String(Math.floor(beat%4)+1).padStart(2,'0');}if(recording){let seconds=now-recordStart;$('#recordStatus').textContent='● REC '+seconds.toFixed(1)+' s'+(battle?' · '+esc(player(battleTurn===0?owner:battleP2).name):'');if(seconds>=(battle?30:300))stopRecording();}raf=requestAnimationFrame(render);}
